function processarEventos(eventos) {
  const vistos = new Set()
  let processados = 0
  let ignorados = 0

  for (const evento of eventos) {
    const id = evento?.id
    if (id === undefined || id === null) {
      processados += 1
      continue
    }
    if (vistos.has(id)) {
      ignorados += 1
      continue
    }
    vistos.add(id)
    processados += 1
  }

  return { processados, ignorados }
}

function quebraCompatibilidade(antes, depois) {
  const removidos = []
  const alterados = []

  for (const [campo, tipo] of Object.entries(antes)) {
    if (!(campo in depois)) {
      removidos.push(`campo removido: ${campo}`)
      continue
    }
    if (depois[campo] !== tipo) {
      alterados.push(`tipo alterado: ${campo}`)
    }
  }

  return [...removidos, ...alterados]
}

