function chaveValida(recebida, ativas, agora) {
  if (!recebida) return false

  const encontrada = ativas.find((chave) => chave.valor === recebida)
  if (!encontrada) return false
  if (encontrada.revogada) return false
  if (!encontrada.expiraEm) return true

  return new Date(encontrada.expiraEm).getTime() > new Date(agora).getTime()
}
